import{_ as o,o as t,c as r,ak as e,al as l,am as i}from"./chunks/framework.C5PBIMEM.js";const m=JSON.parse('{"title":"Godot 4 创建第一个项目教程","description":"","frontmatter":{"0":"i","1":"n","2":"d","3":"e","4":"x","5":":","6":"1"},"headers":[],"relativePath":"godot/godot-4-first-project.md","filePath":"godot/godot-4-first-project.md","lastUpdated":1780926050000}'),d={name:"godot/godot-4-first-project.md"};function s(n,a,h,p,c,g){return t(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="godot-4-创建第一个项目教程" tabindex="-1">Godot 4 创建第一个项目教程 <a class="header-anchor" href="#godot-4-创建第一个项目教程" aria-label="Permalink to “Godot 4 创建第一个项目教程”">​</a></h1><p>本教程适用于搜索以下问题的用户：</p><ul><li>Godot 创建项目</li><li>Godot 新建项目</li><li>Godot 项目管理器</li><li>Godot 第一个项目怎么建</li></ul><p>在完成安装后，接下来最重要的事情就是创建一个项目。<br> Godot 的项目管理器会帮助你管理新项目、已有项目和最近打开的项目。</p><h2 id="一、认识项目管理器" tabindex="-1">一、认识项目管理器 <a class="header-anchor" href="#一、认识项目管理器" aria-label="Permalink to “一、认识项目管理器”">​</a></h2><p>首次启动 Godot 后，你会看到项目管理器界面。<br> 这里通常有三个入口：</p><ul><li>新建项目</li><li>导入项目</li><li>最近打开的项目</li></ul><p>如果你是第一次使用，直接点击 <strong>新建项目</strong> 即可。</p><h2 id="二、建议使用英文目录" tabindex="-1">二、建议使用英文目录 <a class="header-anchor" href="#二、建议使用英文目录" aria-label="Permalink to “二、建议使用英文目录”">​</a></h2><p>创建项目时，建议把项目放在 <strong>英文路径清晰</strong> 的目录下。<br> 这样更方便后续导出、调试和配合插件使用。</p><h2 id="三、点击-新建项目" tabindex="-1">三、点击“新建项目” <a class="header-anchor" href="#三、点击-新建项目" aria-label="Permalink to “三、点击“新建项目””">​</a></h2><p>在项目管理器中点击 <strong>新建项目</strong>。</p><p><img src="'+l+'" alt="Godot 4 Windows 首次启动界面"></p><h2 id="四、填写项目信息" tabindex="-1">四、填写项目信息 <a class="header-anchor" href="#四、填写项目信息" aria-label="Permalink to “四、填写项目信息”">​</a></h2><p>你需要设置：</p><ul><li><strong>项目名称</strong>：例如 <code>godot-hello</code></li><li><strong>项目路径</strong>：建议选择一个干净的英文目录</li><li><strong>渲染器</strong>：新手通常保持默认即可</li></ul><h2 id="五、创建项目" tabindex="-1">五、创建项目 <a class="header-anchor" href="#五、创建项目" aria-label="Permalink to “五、创建项目”">​</a></h2><p>确认无误后，点击创建。<br> Godot 会自动生成项目文件，并打开编辑器。</p><p><img src="'+i+'" alt="Godot 4 Windows 创建项目页面"></p><h2 id="六、创建完成后会看到什么" tabindex="-1">六、创建完成后会看到什么 <a class="header-anchor" href="#六、创建完成后会看到什么" aria-label="Permalink to “六、创建完成后会看到什么”">​</a></h2><p>项目创建成功后，你会进入 Godot 编辑器。<br> 这时项目本身已经建立完成，下一步就是创建场景。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>创建第一个项目其实很简单，只要记住这三步就够了：</p><ol><li>打开项目管理器</li><li>点击新建项目</li><li>选择路径并创建</li></ol><p>下一篇将继续讲：<strong>如何创建第一个场景并运行项目</strong>。</p>',25)])])}const b=o(d,[["render",s]]);export{m as __pageData,b as default};
